import {
  ArrowLeft,
  ArrowUp,
  Bot,
  Check,
  ChevronRight,
  CircleHelp,
  CreditCard,
  Headphones,
  LifeBuoy,
  Loader2,
  LockKeyhole,
  Menu,
  MessageCircleMore,
  PanelLeftClose,
  PanelLeftOpen,
  Plus,
  RotateCcw,
  ShieldCheck,
  Sparkles,
  Store,
  User,
  Wrench,
  X,
} from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { AnimatePresence, motion } from 'motion/react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { useNavigate } from 'react-router-dom';
import { asWerseeAiError, werseeAi } from '../ai/client';
import type { AiAction, AiActionResult, AiMessage, AiStreamEvent } from '../ai/types';
import { firstPublicIdentityLabel } from '../lib/publicIdentity';
import { PageWrapper } from '../components/PageWrapper';
import {
  detectSupportTopic,
  SupportResponseComponents,
  type SupportTopic,
} from '../components/support/SupportResponseComponents';
import { SEO } from '../components/SEO';
import { useAuth } from '../context/AuthContext';
import './liveChat.css';

interface SupportMessage {
  id: string;
  sender: 'user' | 'agent' | 'system';
  text: string;
  timestamp: Date;
  topic?: SupportTopic;
  actions?: AiAction[];
  results?: AiActionResult[];
  error?: { message: string; retryable: boolean };
}

interface QuickTopic {
  id: SupportTopic;
  label: string;
  description: string;
  prompt: string;
  icon: LucideIcon;
  accent: string;
}

const quickTopics: QuickTopic[] = [
  {
    id: 'account',
    label: 'Account & toegang',
    description: 'Inloggen, verificatie en beveiliging',
    prompt: 'Ik heb hulp nodig met mijn account of toegang.',
    icon: LockKeyhole,
    accent: 'from-violet-400/20 to-violet-400/[0.03] text-violet-300',
  },
  {
    id: 'billing',
    label: 'Betalen & facturen',
    description: 'Betalingen, facturen en abonnementen',
    prompt: 'Ik heb een vraag over een betaling, factuur of abonnement.',
    icon: CreditCard,
    accent: 'from-emerald-400/20 to-emerald-400/[0.03] text-emerald-300',
  },
  {
    id: 'selling',
    label: 'Verkopen op Wersee',
    description: 'Producten, winkel en bestellingen',
    prompt: 'Help mij met verkopen, mijn producten of mijn Wersee-winkel.',
    icon: Store,
    accent: 'from-amber-300/20 to-amber-300/[0.03] text-amber-200',
  },
  {
    id: 'technical',
    label: 'Iets werkt niet',
    description: 'Foutmelding, pagina of koppeling',
    prompt: 'Er werkt iets niet goed. Help mij het probleem stap voor stap te onderzoeken.',
    icon: Wrench,
    accent: 'from-blue-400/20 to-blue-400/[0.03] text-blue-300',
  },
];

const welcomeMessage = (name?: string): SupportMessage => ({
  id: 'welcome',
  sender: 'agent',
  text: `Hoi${name ? ` ${name}` : ''}! Ik ben **Wersee Support AI**. Vertel wat er speelt — ik zoek het met je uit en breng je meteen naar de juiste plek.`,
  timestamp: new Date(),
  topic: 'general',
});

const mapAiMessages = (messages: AiMessage[]): SupportMessage[] =>
  messages.flatMap((message) => {
    if (!['user', 'assistant', 'model'].includes(message.role) || !message.content?.trim()) return [];
    const sender = message.role === 'user' ? 'user' : 'agent';
    return [{
      id: message.id,
      sender,
      text: message.content,
      timestamp: new Date(message.created_at),
      topic: detectSupportTopic(message.content),
    } satisfies SupportMessage];
  });

const formatTime = (date: Date) =>
  date.toLocaleTimeString('nl-NL', { hour: '2-digit', minute: '2-digit' });

export const LiveChat = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const displayName = useMemo(
    () => firstPublicIdentityLabel([user?.user_metadata?.full_name, user?.user_metadata?.name, user?.email], ''),
    [user],
  );
  const [messages, setMessages] = useState<SupportMessage[]>(() => [welcomeMessage()]);
  const [conversationId, setConversationId] = useState<string>();
  const [prompt, setPrompt] = useState('');
  const [isLoadingHistory, setIsLoadingHistory] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isResolved, setIsResolved] = useState(false);
  const [lastPrompt, setLastPrompt] = useState('');
  const abortRef = useRef<AbortController | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const hasConversation = messages.some((message) => message.sender === 'user');

  useEffect(() => {
    setMessages((current) => current.length === 1 && current[0].id === 'welcome'
      ? [welcomeMessage(displayName)]
      : current);
  }, [displayName]);

  useEffect(() => {
    if (!user) return;
    let active = true;
    setIsLoadingHistory(true);

    void werseeAi.listConversations()
      .then(async ({ conversations }) => {
        const supportConversation = conversations.find((conversation) =>
          typeof conversation.title === 'string'
          && conversation.title.toLocaleLowerCase('nl-NL').startsWith('wersee support')
          && conversation.status !== 'archived');
        if (!supportConversation || !active) return;
        const detail = await werseeAi.getConversation(supportConversation.id);
        if (!active) return;
        const history = mapAiMessages(detail.messages || []);
        setConversationId(supportConversation.id);
        if (history.length) setMessages([welcomeMessage(displayName), ...history]);
      })
      .catch(() => {
        // A missing history must not block a fresh support conversation.
      })
      .finally(() => {
        if (active) setIsLoadingHistory(false);
      });

    return () => {
      active = false;
    };
  }, [displayName, user]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: hasConversation ? 'smooth' : 'auto' });
  }, [hasConversation, isGenerating, messages]);

  const ensureConversation = useCallback(async () => {
    if (conversationId) return conversationId;
    const { conversation } = await werseeAi.createConversation({
      title: `Wersee Support · ${new Date().toLocaleDateString('nl-NL')}`,
      mode: 'assistant',
    });
    setConversationId(conversation.id);
    return conversation.id as string;
  }, [conversationId]);

  const sendMessage = useCallback(async (rawPrompt: string) => {
    const text = rawPrompt.trim();
    if (!text || isGenerating) return;
    if (!user) {
      setMessages((current) => [...current, {
        id: crypto.randomUUID(),
        sender: 'system',
        text: 'Log in zodat Wersee AI je veilig kan helpen met je account en je supportgesprek kan bewaren.',
        timestamp: new Date(),
        error: { message: 'Je moet ingelogd zijn om Wersee Support AI te gebruiken.', retryable: false },
      }]);
      return;
    }

    const topic = detectSupportTopic(text);
    const userMessage: SupportMessage = {
      id: crypto.randomUUID(),
      sender: 'user',
      text,
      timestamp: new Date(),
      topic,
    };
    const assistantId = crypto.randomUUID();
    setLastPrompt(text);
    setPrompt('');
    setIsResolved(false);
    setMessages((current) => [...current, userMessage, {
      id: assistantId,
      sender: 'agent',
      text: '',
      timestamp: new Date(),
      topic,
      actions: [],
      results: [],
    }]);
    setIsGenerating(true);

    const controller = new AbortController();
    abortRef.current = controller;
    try {
      const currentConversationId = await ensureConversation();
      let streamedText = '';
      let actions: AiAction[] = [];
      let results: AiActionResult[] = [];
      for await (const event of werseeAi.chat({
        conversationId: currentConversationId,
        message: text,
        mode: 'assistant',
        context: {
          page: '/live-chat',
          entityType: 'support',
          selection: { topic },
          capabilities: ['support-guidance', 'page-navigation'],
        },
        signal: controller.signal,
      })) {
        const streamEvent = event as AiStreamEvent;
        if (streamEvent.type === 'message.delta') streamedText += streamEvent.text;
        if (streamEvent.type === 'action.proposed') actions = [...actions, streamEvent.action];
        if (streamEvent.type === 'action.completed') results = [...results, streamEvent.result];
        if (streamEvent.type === 'run.started' && streamEvent.conversationId !== currentConversationId) {
          setConversationId(streamEvent.conversationId);
        }
        setMessages((current) => current.map((message) =>
          message.id === assistantId
            ? { ...message, text: streamedText, actions, results }
            : message));
      }

      if (!streamedText.trim()) {
        setMessages((current) => current.map((message) =>
          message.id === assistantId
            ? { ...message, text: 'Ik kon nog geen volledig antwoord maken. Probeer je vraag iets specifieker te stellen.' }
            : message));
      }
    } catch (reason) {
      if (reason instanceof DOMException && reason.name === 'AbortError') {
        setMessages((current) => current.filter((message) => message.id !== assistantId || Boolean(message.text)));
        return;
      }
      const error = asWerseeAiError(reason, 'Wersee Support AI kon je vraag niet verwerken.');
      setMessages((current) => current.map((message) =>
        message.id === assistantId
          ? {
              ...message,
              text: 'Dat lukte op dit moment niet. Je vraag is niet stilletjes als opgelost gemarkeerd.',
              error: { message: error.message, retryable: error.retryable },
            }
          : message));
    } finally {
      abortRef.current = null;
      setIsGenerating(false);
    }
  }, [ensureConversation, isGenerating, user]);

  const startNewConversation = useCallback(async () => {
    abortRef.current?.abort();
    if (conversationId) {
      try {
        await werseeAi.archiveConversation(conversationId);
      } catch {
        // Starting locally still gives the user a usable fresh surface.
      }
    }
    setConversationId(undefined);
    setMessages([welcomeMessage(displayName)]);
    setIsResolved(false);
    setPrompt('');
    setIsMobileMenuOpen(false);
    textareaRef.current?.focus();
  }, [conversationId, displayName]);

  const contactSpecialist = useCallback(() => {
    const summary = lastPrompt
      ? `Mijn laatste supportvraag was: ${lastPrompt}`
      : 'Ik wil graag hulp van een Wersee-supportspecialist.';
    window.location.href = `mailto:support@wersee.com?subject=${encodeURIComponent('Hulp nodig via Wersee Support')}&body=${encodeURIComponent(`${summary}\n\nMijn account: ${user?.email || 'niet ingevuld'}`)}`;
  }, [lastPrompt, user?.email]);

  const submitPrompt = (event?: React.FormEvent) => {
    event?.preventDefault();
    void sendMessage(prompt);
  };

  const sidebar = (
    <div className="flex h-full flex-col">
      <div className="border-b border-white/[0.07] p-5">
        <button
          type="button"
          onClick={() => navigate('/')}
          className="mb-7 inline-flex items-center gap-2 text-xs font-semibold text-zinc-500 transition hover:text-white"
        >
          <ArrowLeft className="h-4 w-4" />
          Terug naar Wersee
        </button>
        <div className="flex items-center gap-3">
          <span className="grid h-11 w-11 place-items-center rounded-2xl bg-gradient-to-br from-blue-400 to-blue-600 text-white shadow-lg shadow-blue-500/15">
            <LifeBuoy className="h-5 w-5" />
          </span>
          <div>
            <p className="text-sm font-semibold text-white">Wersee Support</p>
            <p className="mt-0.5 text-xs text-zinc-500">AI-hulp en specialistische support</p>
          </div>
        </div>
        <button
          type="button"
          onClick={() => void startNewConversation()}
          className="mt-6 flex w-full items-center justify-center gap-2 rounded-xl border border-white/10 bg-white/[0.045] px-4 py-3 text-sm font-semibold text-zinc-200 transition hover:border-blue-400/30 hover:bg-blue-400/[0.08]"
        >
          <Plus className="h-4 w-4" />
          Nieuw supportgesprek
        </button>
      </div>

      <div className="flex-1 p-3">
        <p className="px-2 pb-2 pt-1 text-[10px] font-semibold uppercase tracking-[0.2em] text-zinc-600">Huidig gesprek</p>
        <div className="rounded-2xl border border-blue-400/20 bg-blue-400/[0.07] p-3.5">
          <div className="flex items-center gap-3">
            <span className="relative grid h-10 w-10 place-items-center rounded-xl bg-blue-400/10 text-blue-300">
              <Bot className="h-4.5 w-4.5" />
              <span className="absolute -bottom-0.5 -right-0.5 h-3 w-3 rounded-full border-2 border-[#0b0d12] bg-emerald-400" />
            </span>
            <div className="min-w-0 flex-1">
              <p className="truncate text-sm font-semibold text-zinc-100">Support AI</p>
              <p className="mt-0.5 truncate text-xs text-zinc-500">
                {hasConversation ? messages.at(-1)?.text || 'Bezig met antwoorden…' : 'Klaar om te helpen'}
              </p>
            </div>
          </div>
        </div>
      </div>

      <div className="border-t border-white/[0.07] p-4">
        <div className="flex items-center gap-3 rounded-2xl bg-white/[0.025] p-3">
          <span className="grid h-9 w-9 place-items-center rounded-xl bg-white/[0.07] text-xs font-bold text-white">
            {(displayName || user?.email || 'W').charAt(0).toUpperCase()}
          </span>
          <div className="min-w-0 flex-1">
            <p className="truncate text-xs font-semibold text-zinc-200">{displayName || 'Wersee gebruiker'}</p>
            <p className="truncate text-[11px] text-zinc-600">{user?.email || 'Niet ingelogd'}</p>
          </div>
          <ShieldCheck className="h-4 w-4 text-zinc-600" />
        </div>
      </div>
    </div>
  );

  return (
    <PageWrapper>
      <SEO
        title="AI Support & Live Chat - Wersee"
        description="Krijg direct hulp van Wersee Support AI of neem contact op met een supportspecialist."
        url="/live-chat"
        noIndex
      />
      <div className="flex h-[100dvh] overflow-hidden bg-[#08090c] text-white">
        <AnimatePresence initial={false}>
          {isSidebarOpen ? (
            <motion.aside
              initial={{ width: 0, opacity: 0 }}
              animate={{ width: 304, opacity: 1 }}
              exit={{ width: 0, opacity: 0 }}
              className="hidden shrink-0 overflow-hidden border-r border-white/[0.07] bg-[#0b0d12] lg:block"
            >
              <div className="h-full w-[304px]">{sidebar}</div>
            </motion.aside>
          ) : null}
        </AnimatePresence>

        <AnimatePresence>
          {isMobileMenuOpen ? (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 z-[80] lg:hidden"
            >
              <button
                type="button"
                aria-label="Menu sluiten"
                className="absolute inset-0 bg-black/70 backdrop-blur-sm"
                onClick={() => setIsMobileMenuOpen(false)}
              />
              <motion.aside
                initial={{ x: '-100%' }}
                animate={{ x: 0 }}
                exit={{ x: '-100%' }}
                transition={{ type: 'spring', damping: 28, stiffness: 260 }}
                className="relative h-full w-[min(88vw,320px)] border-r border-white/10 bg-[#0b0d12]"
              >
                <button
                  type="button"
                  onClick={() => setIsMobileMenuOpen(false)}
                  aria-label="Menu sluiten"
                  className="absolute right-3 top-3 z-10 grid h-9 w-9 place-items-center rounded-xl bg-white/[0.06] text-zinc-400"
                >
                  <X className="h-4 w-4" />
                </button>
                {sidebar}
              </motion.aside>
            </motion.div>
          ) : null}
        </AnimatePresence>

        <main className="relative flex min-w-0 flex-1 flex-col bg-[radial-gradient(circle_at_50%_-20%,rgba(37,99,235,0.15),transparent_38%)]">
          <header className="z-20 flex h-[76px] shrink-0 items-center justify-between border-b border-white/[0.07] bg-[#0b0d12]/85 px-4 backdrop-blur-xl sm:px-6">
            <div className="flex min-w-0 items-center gap-3">
              <button
                type="button"
                onClick={() => setIsMobileMenuOpen(true)}
                aria-label="Supportmenu openen"
                className="grid h-10 w-10 shrink-0 place-items-center rounded-xl border border-white/[0.08] text-zinc-400 lg:hidden"
              >
                <Menu className="h-4.5 w-4.5" />
              </button>
              <button
                type="button"
                onClick={() => setIsSidebarOpen((value) => !value)}
                aria-label={isSidebarOpen ? 'Zijbalk sluiten' : 'Zijbalk openen'}
                className="support-header-sidebar-toggle h-10 w-10 shrink-0 place-items-center rounded-xl border border-white/[0.08] text-zinc-500 transition hover:text-white"
              >
                {isSidebarOpen ? <PanelLeftClose className="h-4.5 w-4.5" /> : <PanelLeftOpen className="h-4.5 w-4.5" />}
              </button>
              <span className="relative grid h-11 w-11 shrink-0 place-items-center rounded-2xl bg-blue-500/12 text-blue-300">
                <Bot className="h-5 w-5" />
                <span className="absolute -bottom-0.5 -right-0.5 h-3 w-3 rounded-full border-2 border-[#0b0d12] bg-emerald-400" />
              </span>
              <div className="min-w-0">
                <div className="flex items-center gap-2">
                  <h1 className="truncate text-sm font-semibold sm:text-base">Wersee Support AI</h1>
                  <span className="hidden rounded-full bg-blue-400/10 px-2 py-1 text-[9px] font-bold uppercase tracking-[0.14em] text-blue-300 sm:inline">AI</span>
                </div>
                <p className="mt-0.5 flex items-center gap-1.5 text-[11px] text-zinc-500">
                  <span className="h-1.5 w-1.5 rounded-full bg-emerald-400" />
                  Direct beschikbaar
                </p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={contactSpecialist}
                className="support-header-specialist items-center gap-2 rounded-xl border border-white/[0.08] bg-white/[0.035] px-3.5 py-2.5 text-xs font-semibold text-zinc-300 transition hover:border-white/15 hover:bg-white/[0.07]"
              >
                <Headphones className="h-4 w-4" />
                Specialist
              </button>
              <button
                type="button"
                onClick={() => setIsResolved((value) => !value)}
                className={`grid h-10 w-10 place-items-center rounded-xl border transition ${
                  isResolved
                    ? 'border-emerald-400/25 bg-emerald-400/10 text-emerald-300'
                    : 'border-white/[0.08] text-zinc-500 hover:text-white'
                }`}
                aria-label={isResolved ? 'Gesprek heropenen' : 'Markeren als opgelost'}
                title={isResolved ? 'Gesprek heropenen' : 'Markeren als opgelost'}
              >
                {isResolved ? <RotateCcw className="h-4 w-4" /> : <Check className="h-4 w-4" />}
              </button>
            </div>
          </header>

          <section className="flex-1 overflow-y-auto overscroll-contain">
            <div className={`mx-auto flex min-h-full w-full max-w-4xl flex-col px-4 sm:px-6 ${hasConversation ? 'py-6' : 'justify-center py-8'}`}>
              {!hasConversation ? (
                <div className="mx-auto w-full max-w-3xl">
                  <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} className="text-center">
                    <span className="mx-auto grid h-16 w-16 place-items-center rounded-[22px] border border-blue-300/15 bg-gradient-to-br from-blue-400/20 to-violet-400/10 text-blue-200 shadow-2xl shadow-blue-500/10">
                      <Sparkles className="h-7 w-7" />
                    </span>
                    <p className="mt-6 text-xs font-semibold uppercase tracking-[0.2em] text-blue-300/80">Wersee Support AI</p>
                    <h2 className="mx-auto mt-3 max-w-2xl text-balance text-3xl font-semibold tracking-[-0.035em] text-white sm:text-4xl">
                      Hoi{displayName ? ` ${displayName}` : ''}, waar kunnen we mee helpen?
                    </h2>
                    <p className="mx-auto mt-3 max-w-xl text-pretty text-sm leading-6 text-zinc-500 sm:text-base">
                      Beschrijf je vraag in je eigen woorden. Wersee AI denkt mee, toont de juiste onderdelen en schakelt je zo nodig door.
                    </p>
                  </motion.div>

                  <div className="mt-8 grid gap-3 sm:grid-cols-2">
                    {quickTopics.map((topic, index) => {
                      const Icon = topic.icon;
                      return (
                        <motion.button
                          key={topic.id}
                          type="button"
                          initial={{ opacity: 0, y: 10 }}
                          animate={{ opacity: 1, y: 0 }}
                          transition={{ delay: 0.04 * index }}
                          onClick={() => void sendMessage(topic.prompt)}
                          className="group flex min-h-24 items-center gap-4 rounded-2xl border border-white/[0.08] bg-white/[0.025] p-4 text-left transition hover:-translate-y-0.5 hover:border-white/15 hover:bg-white/[0.045]"
                        >
                          <span className={`grid h-11 w-11 shrink-0 place-items-center rounded-2xl bg-gradient-to-br ${topic.accent}`}>
                            <Icon className="h-5 w-5" />
                          </span>
                          <span className="min-w-0 flex-1">
                            <span className="block text-sm font-semibold text-zinc-100">{topic.label}</span>
                            <span className="mt-1 block text-xs leading-5 text-zinc-500">{topic.description}</span>
                          </span>
                          <ChevronRight className="h-4 w-4 text-zinc-700 transition group-hover:translate-x-0.5 group-hover:text-zinc-400" />
                        </motion.button>
                      );
                    })}
                  </div>
                  <div className="mt-5 flex items-center justify-center gap-5 text-[11px] text-zinc-600">
                    <span className="flex items-center gap-1.5"><ShieldCheck className="h-3.5 w-3.5" /> Beveiligde verbinding</span>
                    <span className="flex items-center gap-1.5">
                      <MessageCircleMore className="h-3.5 w-3.5" />
                      {user ? 'Gesprek wordt bewaard' : 'Log in om je gesprek te bewaren'}
                    </span>
                  </div>
                </div>
              ) : (
                <div className="space-y-7">
                  {messages.map((message) => (
                    <motion.article
                      key={message.id}
                      initial={{ opacity: 0, y: 8 }}
                      animate={{ opacity: 1, y: 0 }}
                      className={`flex gap-3 ${message.sender === 'user' ? 'justify-end' : 'justify-start'}`}
                    >
                      {message.sender !== 'user' ? (
                        <span className={`mt-1 grid h-8 w-8 shrink-0 place-items-center rounded-xl ${
                          message.sender === 'system' ? 'bg-amber-400/10 text-amber-300' : 'bg-blue-400/10 text-blue-300'
                        }`}>
                          {message.sender === 'system' ? <CircleHelp className="h-4 w-4" /> : <Bot className="h-4 w-4" />}
                        </span>
                      ) : null}
                      <div className={`min-w-0 ${message.sender === 'user' ? 'max-w-[82%] sm:max-w-[70%]' : 'max-w-[90%] sm:max-w-[78%]'}`}>
                        <div className={`rounded-3xl px-4 py-3.5 sm:px-5 ${
                          message.sender === 'user'
                            ? 'rounded-tr-lg bg-blue-500 text-white shadow-lg shadow-blue-500/10'
                            : message.sender === 'system'
                              ? 'rounded-tl-lg border border-amber-300/15 bg-amber-300/[0.04] text-zinc-300'
                              : 'rounded-tl-lg border border-white/[0.075] bg-[#111319] text-zinc-200'
                        }`}>
                          {message.text ? (
                            <div className="markdown-body text-sm leading-6">
                              <ReactMarkdown remarkPlugins={[remarkGfm]}>{message.text}</ReactMarkdown>
                            </div>
                          ) : (
                            <div className="flex items-center gap-2 py-1 text-sm text-zinc-500">
                              <Loader2 className="h-4 w-4 animate-spin text-blue-300" />
                              Wersee AI zoekt dit voor je uit…
                            </div>
                          )}
                          {message.error ? (
                            <div className="mt-3 rounded-2xl border border-red-400/15 bg-red-400/[0.06] p-3">
                              <p className="text-xs leading-5 text-red-200">{message.error.message}</p>
                              <div className="mt-2 flex flex-wrap gap-2">
                                {message.error.retryable && lastPrompt ? (
                                  <button
                                    type="button"
                                    onClick={() => void sendMessage(lastPrompt)}
                                    className="rounded-lg bg-red-300/10 px-2.5 py-1.5 text-[11px] font-semibold text-red-100 transition hover:bg-red-300/15"
                                  >
                                    Opnieuw proberen
                                  </button>
                                ) : null}
                                {!user ? (
                                  <button
                                    type="button"
                                    onClick={() => navigate(`/auth?returnTo=${encodeURIComponent('/live-chat')}`)}
                                    className="rounded-lg bg-white/10 px-2.5 py-1.5 text-[11px] font-semibold text-white transition hover:bg-white/15"
                                  >
                                    Inloggen
                                  </button>
                                ) : null}
                              </div>
                            </div>
                          ) : null}
                        </div>
                        {message.sender === 'agent' && message.text && message.id !== 'welcome' && !message.error ? (
                          <SupportResponseComponents
                            topic={message.topic || 'general'}
                            actions={message.actions}
                            results={message.results}
                            onFollowUp={(value) => void sendMessage(value)}
                          />
                        ) : null}
                        <p className={`mt-1.5 text-[10px] text-zinc-700 ${message.sender === 'user' ? 'text-right' : ''}`}>
                          {formatTime(message.timestamp)}
                        </p>
                      </div>
                      {message.sender === 'user' ? (
                        <span className="mt-1 hidden h-8 w-8 shrink-0 place-items-center rounded-xl bg-white/[0.06] text-zinc-400 sm:grid">
                          <User className="h-4 w-4" />
                        </span>
                      ) : null}
                    </motion.article>
                  ))}
                  {isResolved ? (
                    <div className="mx-auto max-w-md rounded-2xl border border-emerald-300/15 bg-emerald-300/[0.05] p-4 text-center">
                      <p className="text-sm font-semibold text-emerald-200">Gemarkeerd als opgelost</p>
                      <p className="mt-1 text-xs leading-5 text-zinc-500">Je kunt dit gesprek altijd heropenen of een nieuw gesprek starten.</p>
                    </div>
                  ) : null}
                  <div ref={messagesEndRef} />
                </div>
              )}
            </div>
          </section>

          <footer className="shrink-0 border-t border-white/[0.05] bg-[#08090c]/90 px-3 pb-[max(12px,env(safe-area-inset-bottom))] pt-3 backdrop-blur-xl sm:px-6 sm:pb-5">
            <form onSubmit={submitPrompt} className="mx-auto max-w-3xl">
              <div className="rounded-[22px] border border-white/[0.1] bg-[#111319] p-2 shadow-2xl shadow-black/30 transition focus-within:border-blue-400/35">
                <textarea
                  ref={textareaRef}
                  value={prompt}
                  onChange={(event) => setPrompt(event.target.value)}
                  onKeyDown={(event) => {
                    if (event.key === 'Enter' && !event.shiftKey) {
                      event.preventDefault();
                      submitPrompt();
                    }
                  }}
                  rows={1}
                  disabled={isGenerating || isResolved}
                  placeholder={isResolved ? 'Heropen het gesprek om verder te gaan' : 'Vertel ons waarmee je hulp nodig hebt…'}
                  className="max-h-32 min-h-11 w-full resize-none bg-transparent px-3 py-3 text-sm leading-5 text-white outline-none placeholder:text-zinc-600 disabled:cursor-not-allowed"
                />
                <div className="flex items-center justify-between gap-3 px-1 pb-1">
                  <div className="flex min-w-0 items-center gap-2 text-[10px] text-zinc-600">
                    <Sparkles className="h-3.5 w-3.5 text-blue-400/70" />
                    <span className="truncate">Wersee AI kan fouten maken. Controleer belangrijke informatie.</span>
                  </div>
                  {isGenerating ? (
                    <button
                      type="button"
                      onClick={() => abortRef.current?.abort()}
                      className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-white text-black transition hover:bg-zinc-200"
                      aria-label="Antwoord stoppen"
                    >
                      <span className="h-3 w-3 rounded-sm bg-black" />
                    </button>
                  ) : (
                    <button
                      type="submit"
                      disabled={!prompt.trim() || isResolved}
                      className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-blue-500 text-white shadow-lg shadow-blue-500/20 transition hover:bg-blue-400 disabled:cursor-not-allowed disabled:bg-white/[0.06] disabled:text-zinc-700 disabled:shadow-none"
                      aria-label="Bericht versturen"
                    >
                      <ArrowUp className="h-4 w-4" />
                    </button>
                  )}
                </div>
              </div>
              <button
                type="button"
                onClick={contactSpecialist}
                className="mx-auto mt-2 flex items-center gap-1.5 text-[11px] text-zinc-600 transition hover:text-zinc-300 sm:hidden"
              >
                <Headphones className="h-3.5 w-3.5" />
                Liever hulp van een specialist?
              </button>
            </form>
          </footer>

          {isLoadingHistory ? (
            <div className="pointer-events-none absolute inset-x-0 top-[76px] z-10 flex justify-center">
              <div className="mt-3 flex items-center gap-2 rounded-full border border-white/[0.08] bg-[#111319]/90 px-3 py-1.5 text-[10px] text-zinc-500 shadow-lg backdrop-blur">
                <Loader2 className="h-3 w-3 animate-spin" />
                Vorig gesprek laden
              </div>
            </div>
          ) : null}
        </main>
      </div>
    </PageWrapper>
  );
};
