import React from 'react';
import {
  ArrowUpRight,
  BadgeEuro,
  BookOpen,
  CheckCircle2,
  CreditCard,
  LifeBuoy,
  LockKeyhole,
  Package,
  Settings2,
  ShieldCheck,
  Store,
  Wrench,
} from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import type { AiAction, AiActionResult } from '../../ai/types';

export type SupportTopic = 'account' | 'billing' | 'selling' | 'technical' | 'general';

export interface SupportPageLink {
  title: string;
  description: string;
  path: string;
  icon: LucideIcon;
}

const topicLinks: Record<SupportTopic, SupportPageLink[]> = {
  account: [
    { title: 'Accountinstellingen', description: 'Beheer je profiel en voorkeuren', path: '/workspace/profile', icon: Settings2 },
    { title: 'Accountbeveiliging', description: 'Wachtwoord, sessies en beveiliging', path: '/account-security', icon: ShieldCheck },
  ],
  billing: [
    { title: 'Facturen', description: 'Bekijk en beheer je Wersee-facturen', path: '/workspace/money-invoices', icon: BadgeEuro },
    { title: 'Betaalmethoden', description: 'Beheer gekoppelde betaalmethoden', path: '/workspace/money-methods', icon: CreditCard },
  ],
  selling: [
    { title: 'Producten beheren', description: 'Open je producten en publicaties', path: '/workspace/management-products', icon: Package },
    { title: 'Store Health', description: 'Controleer de status van je winkel', path: '/workspace/management-store-health', icon: Store },
  ],
  technical: [
    { title: 'Status van Wersee', description: 'Controleer actuele systeemstatus', path: '/status', icon: Wrench },
    { title: 'Documentatie', description: 'Vind technische uitleg en handleidingen', path: '/community/docs', icon: BookOpen },
  ],
  general: [
    { title: 'Helpcentrum', description: 'Bekijk alle hulp en veelgestelde vragen', path: '/support', icon: LifeBuoy },
    { title: 'Privacy en veiligheid', description: 'Lees hoe Wersee met data omgaat', path: '/privacy', icon: LockKeyhole },
  ],
};

const includesAny = (value: string, terms: string[]) => terms.some((term) => value.includes(term));

export const detectSupportTopic = (value: string): SupportTopic => {
  const text = value.toLocaleLowerCase('nl-NL');
  if (includesAny(text, ['betaal', 'betaling', 'factuur', 'refund', 'terugbetal', 'abonnement', 'stripe', 'prijs'])) return 'billing';
  if (includesAny(text, ['inlog', 'account', 'wachtwoord', 'profiel', 'beveilig', 'verificatie', 'email', 'e-mail'])) return 'account';
  if (includesAny(text, ['product', 'verkopen', 'winkel', 'listing', 'publicer', 'marketplace', 'bestelling'])) return 'selling';
  if (includesAny(text, ['fout', 'error', 'werkt niet', 'bug', 'laden', 'technisch', 'api', 'koppeling', 'crash'])) return 'technical';
  return 'general';
};

interface SupportResponseComponentsProps {
  topic: SupportTopic;
  actions?: AiAction[];
  results?: AiActionResult[];
  onFollowUp: (prompt: string) => void;
}

export const SupportResponseComponents = ({
  topic,
  actions = [],
  results = [],
  onFollowUp,
}: SupportResponseComponentsProps) => {
  const navigate = useNavigate();
  const links = topicLinks[topic];

  return (
    <div className="mt-3 grid gap-3">
      {results.map((result, index) => (
        <div key={`${result.summary}-${index}`} className="rounded-2xl border border-emerald-400/20 bg-emerald-400/[0.06] p-4">
          <div className="flex items-start gap-3">
            <span className="grid h-8 w-8 shrink-0 place-items-center rounded-xl bg-emerald-400/10 text-emerald-400">
              <CheckCircle2 className="h-4 w-4" />
            </span>
            <div className="min-w-0">
              <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-emerald-400">Controle voltooid</p>
              <p className="mt-1 text-sm leading-6 text-zinc-300">{result.summary}</p>
              {result.resource?.route ? (
                <button
                  type="button"
                  onClick={() => navigate(result.resource!.route!)}
                  className="mt-3 inline-flex items-center gap-1.5 text-xs font-semibold text-emerald-300 transition hover:text-emerald-200"
                >
                  {result.resource.label}
                  <ArrowUpRight className="h-3.5 w-3.5" />
                </button>
              ) : null}
            </div>
          </div>
        </div>
      ))}

      {actions.map((action) => (
        <div key={action.id} className="rounded-2xl border border-amber-300/20 bg-amber-300/[0.05] p-4">
          <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-amber-300">Voorstel van Wersee AI</p>
          <p className="mt-1 text-sm font-semibold text-white">{action.title || action.preview?.title || 'Voorgestelde actie'}</p>
          {action.preview?.summary ? <p className="mt-1 text-sm leading-6 text-zinc-400">{action.preview.summary}</p> : null}
          <p className="mt-3 text-xs text-zinc-500">Deze supportpagina voert geen wijziging uit zonder jouw bevestiging.</p>
        </div>
      ))}

      <div className="grid gap-2 sm:grid-cols-2">
        {links.map((link) => {
          const Icon = link.icon;
          return (
            <button
              key={link.path}
              type="button"
              onClick={() => navigate(link.path)}
              className="group flex min-h-20 items-center gap-3 rounded-2xl border border-white/[0.08] bg-white/[0.035] p-3.5 text-left transition hover:border-blue-400/30 hover:bg-blue-400/[0.06]"
            >
              <span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-white/[0.06] text-zinc-300 transition group-hover:bg-blue-400/10 group-hover:text-blue-300">
                <Icon className="h-4.5 w-4.5" />
              </span>
              <span className="min-w-0 flex-1">
                <span className="block text-sm font-semibold text-zinc-100">{link.title}</span>
                <span className="mt-0.5 block text-xs leading-5 text-zinc-500">{link.description}</span>
              </span>
              <ArrowUpRight className="h-4 w-4 shrink-0 text-zinc-600 transition group-hover:text-blue-300" />
            </button>
          );
        })}
      </div>

      <div className="flex flex-wrap gap-2">
        <button
          type="button"
          onClick={() => onFollowUp('Leg dit korter uit in concrete stappen.')}
          className="rounded-full border border-white/10 bg-white/[0.04] px-3 py-2 text-xs font-medium text-zinc-400 transition hover:border-white/20 hover:text-white"
        >
          Geef mij de stappen
        </button>
        <button
          type="button"
          onClick={() => onFollowUp('Wat heb je nog van mij nodig om dit probleem verder te onderzoeken?')}
          className="rounded-full border border-white/10 bg-white/[0.04] px-3 py-2 text-xs font-medium text-zinc-400 transition hover:border-white/20 hover:text-white"
        >
          Verder onderzoeken
        </button>
      </div>
    </div>
  );
};
